-- ========================================================
-- NovaMart: Complete Supabase Schema & Initial Data Dump
-- Open Supabase -> SQL Editor -> New Query -> Paste & Run
-- ========================================================

-- 1. Clean reset of existing tables and types
DROP TABLE IF EXISTS reviews, order_items, orders, cart_items, carts, product_embeddings, product_images, products, categories, addresses, users CASCADE;
DROP TYPE IF EXISTS user_role CASCADE;
DROP TYPE IF EXISTS order_status CASCADE;

-- 2. Extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "vector";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";

-- 3. Custom Enum Types
CREATE TYPE user_role AS ENUM ('customer', 'seller', 'admin', 'CUSTOMER', 'SELLER', 'ADMIN');
CREATE TYPE order_status AS ENUM ('pending', 'confirmed', 'processing', 'shipped', 'delivered', 'cancelled', 'refunded', 'PENDING', 'CONFIRMED', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'CANCELLED', 'REFUNDED');

-- 4. Table Definitions
CREATE TABLE IF NOT EXISTS users (
	email VARCHAR(255) NOT NULL, 
	hashed_password VARCHAR(255) NOT NULL, 
	full_name VARCHAR(150) NOT NULL, 
	role user_role NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS addresses (
	user_id UUID NOT NULL, 
	label VARCHAR(50) NOT NULL, 
	full_name VARCHAR(150) NOT NULL, 
	street_address VARCHAR(300) NOT NULL, 
	city VARCHAR(100) NOT NULL, 
	state VARCHAR(100) NOT NULL, 
	postal_code VARCHAR(20) NOT NULL, 
	country VARCHAR(100) NOT NULL, 
	is_default BOOLEAN NOT NULL, 
	id UUID NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE TABLE IF NOT EXISTS categories (
	name VARCHAR(100) NOT NULL, 
	slug VARCHAR(120) NOT NULL, 
	description TEXT, 
	icon VARCHAR(10), 
	parent_id UUID, 
	sort_order INTEGER NOT NULL, 
	id UUID NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name), 
	FOREIGN KEY(parent_id) REFERENCES categories (id)
);

CREATE TABLE IF NOT EXISTS products (
	sku VARCHAR(50) NOT NULL, 
	title VARCHAR(300) NOT NULL, 
	slug VARCHAR(350) NOT NULL, 
	description TEXT NOT NULL, 
	short_description VARCHAR(500) NOT NULL, 
	price NUMERIC(10, 2) NOT NULL, 
	compare_at_price NUMERIC(10, 2), 
	stock_quantity INTEGER NOT NULL, 
	category_id UUID NOT NULL, 
	brand VARCHAR(100), 
	attributes JSONB DEFAULT '{}' NOT NULL, 
	tags VARCHAR[] DEFAULT '{}' NOT NULL, 
	avg_rating NUMERIC(3, 2) NOT NULL, 
	review_count INTEGER NOT NULL, 
	is_published BOOLEAN NOT NULL, 
	is_featured BOOLEAN NOT NULL, 
	id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_products_price_positive CHECK (price > 0), 
	CONSTRAINT ck_products_stock_non_negative CHECK (stock_quantity >= 0), 
	CONSTRAINT ck_products_compare_price CHECK (compare_at_price IS NULL OR compare_at_price > price), 
	FOREIGN KEY(category_id) REFERENCES categories (id)
);

CREATE TABLE IF NOT EXISTS product_images (
	product_id UUID NOT NULL, 
	url VARCHAR(500) NOT NULL, 
	alt_text VARCHAR(200), 
	sort_order INTEGER NOT NULL, 
	id UUID NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS product_embeddings (
	product_id UUID NOT NULL, 
	embedding VECTOR(384) NOT NULL, 
	embedding_model VARCHAR(100) NOT NULL, 
	embedding_text TEXT NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	id UUID NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (product_id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS carts (
	user_id UUID NOT NULL, 
	id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS cart_items (
	cart_id UUID NOT NULL, 
	product_id UUID NOT NULL, 
	quantity INTEGER NOT NULL, 
	id UUID NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_cart_item_product UNIQUE (cart_id, product_id), 
	CONSTRAINT ck_cart_items_quantity_positive CHECK (quantity > 0), 
	FOREIGN KEY(cart_id) REFERENCES carts (id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (id)
);

CREATE TABLE IF NOT EXISTS orders (
	order_number VARCHAR(20) NOT NULL, 
	user_id UUID NOT NULL, 
	status order_status NOT NULL, 
	shipping_address_id UUID, 
	subtotal NUMERIC(12, 2) NOT NULL, 
	tax_amount NUMERIC(10, 2) NOT NULL, 
	total NUMERIC(12, 2) NOT NULL, 
	notes TEXT, 
	id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(shipping_address_id) REFERENCES addresses (id)
);

CREATE TABLE IF NOT EXISTS order_items (
	order_id UUID NOT NULL, 
	product_id UUID NOT NULL, 
	product_title VARCHAR(300) NOT NULL, 
	product_sku VARCHAR(50) NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	total_price NUMERIC(12, 2) NOT NULL, 
	id UUID NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_order_items_quantity_positive CHECK (quantity > 0), 
	CONSTRAINT ck_order_items_price_positive CHECK (unit_price > 0), 
	FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (id)
);

CREATE TABLE IF NOT EXISTS reviews (
	product_id UUID NOT NULL, 
	user_id UUID NOT NULL, 
	rating INTEGER NOT NULL, 
	title VARCHAR(200), 
	body TEXT, 
	is_verified_purchase BOOLEAN NOT NULL, 
	id UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_review_user_product UNIQUE (product_id, user_id), 
	CONSTRAINT ck_reviews_rating_range CHECK (rating >= 1 AND rating <= 5), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id)
);

