INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('98266974-5a5f-49b1-9a3f-6fc8d8e2bbc0', 'NM-82D8E0FB', 'Ray-Ban Original Wayfarer Polarized Sunglasses (Tortoise Frame / Green Classic G-15)', 'ray-ban-original-wayfarer-polarized-sunglasses-tortoise-frame-green-classic-g-15', 'Ray-Ban Original Wayfarer Classics are the most recognizable style in the history of sunglasses. Since its initial design in 1952, Wayfarer Classics gained popularity among celebrities, musicians, artists and those with an impeccable fashion sense.', '100% UV protection, high quality polarized crystal lenses, iconic acetate frame.', 221.00, 245.00, 47, '92292d4b-f991-4511-93bd-4f83e8672c60', 'Ray-Ban', '{"dimensions": "Lens width: 50mm, Bridge: 22mm, Temple: 150mm", "uv_protection": "100% UVA/UVB protection (UV400)", "frame_material": "Hypoallergenic Handcrafted Acetate", "lens_technology": "Polarized Crystal Green G-15 (absorbs 85% of visible light)"}'::jsonb, ARRAY['rayban', 'sunglasses', 'wayfarer', 'polarized', 'eyewear', 'classic', 'bestseller']::varchar[], 5.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('61ecb783-e3af-4e4d-b2a6-5d5d4b2a4911', 'NM-58EE8210', 'Sony PlayStation 5 Slim Console (1TB SSD, DualSense Wireless Controller)', 'sony-playstation-5-slim-console-1tb-ssd-dualsense-wireless-controller', 'Experience lightning-fast loading with an ultra-high-speed SSD, deeper immersion with haptic feedback, adaptive triggers, and 3D Audio, plus an all-new generation of incredible PlayStation games. Packed into a sleek, compact slim chassis with 1TB internal high-speed storage.', 'Slim design with 1TB SSD storage, 4K-TV gaming, Ray Tracing, and Tempest 3D AudioTech.', 499.99, 549.99, 40, '47734feb-7f89-4f3a-abd0-52f7d03d0016', 'Sony', '{"audio": "Tempest 3D AudioTech engine", "storage": "1TB Custom High-Speed NVMe SSD", "controller": "DualSense Wireless Controller with Haptic Feedback", "resolution": "Up to 4K 120Hz, 8K output support"}'::jsonb, ARRAY['sony', 'playstation', 'ps5', 'gaming', 'console', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('11f94b6c-fb1b-4578-a91d-fae917249d68', 'NM-F28EAEA2', 'Amazon Kindle Paperwhite (16GB, 6.8" Glare-Free Display, Warm Light)', 'amazon-kindle-paperwhite-16gb-6-8-glare-free-display-warm-light', 'Now with a 6.8" display and thinner borders, adjustable warm light, up to 10 weeks of battery life, and 20% faster page turns. Purpose-built for reading with a flush-front design and 300 ppi glare-free display that reads like real paper even in bright sunlight.', '6.8" 300 ppi display, adjustable warm light, up to 10 weeks battery life, waterproof IPX8.', 149.99, 169.99, 65, 'b0cedd18-d2ea-4745-9ff6-26099432e969', 'Amazon', '{"display": "6.8\" Paperwhite display with built-in light, 300 ppi", "storage": "16GB (Holds thousands of books)", "battery_life": "Up to 10 weeks on a single charge", "waterproofing": "IPX8 (Submersion in 2 meters fresh water for 60 min)"}'::jsonb, ARRAY['amazon', 'kindle', 'ereader', 'books', 'reading', 'paperwhite', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('435e31db-9203-4da6-843d-9740aedc01b5', 'NM-EDF66870', 'Logitech MX Master 3S Wireless Performance Mouse - Graphite', 'logitech-mx-master-3s-wireless-performance-mouse-graphite', 'An icon remastered. Feel every single moment of your workflow with even more precision, tactility, and performance, thanks to Quiet Clicks and an 8,000 DPI track-on-glass sensor. The MagSpeed electromagnetic scroll wheel provides unmatched speed and silence.', 'Quiet Clicks, 8K DPI any-surface tracking, MagSpeed electromagnetic scrolling wheel.', 99.99, 119.99, 70, '47734feb-7f89-4f3a-abd0-52f7d03d0016', 'Logitech', '{"scroll": "MagSpeed SmartShift electromagnetic scrolling wheel", "sensor": "Darkfield high precision, 200 to 8000 DPI (set in increments of 50 DPI)", "battery": "Rechargeable Li-Po (500 mAh) battery, up to 70 days on a full charge", "buttons": "7 buttons (Left/Right-click, Back/Forward, App-Switch, Wheel mode-shift, Middle click)"}'::jsonb, ARRAY['logitech', 'mouse', 'mxmaster', 'ergonomic', 'productivity', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('5342f308-160c-4229-ae02-700afd5b7449', 'NM-E0E18139', 'Marshall Stanmore III Bluetooth Home Speaker - Black', 'marshall-stanmore-iii-bluetooth-home-speaker-black', 'As the middleweight speaker of the home line-up, Stanmore III brings expansive Marshall sound to any room. It has outward-angled tweeters and updated waveguides to deliver a consistently solid sound that is so wide it chases you around the room.', 'Room-filling Marshall signature sound, re-engineered wider stereo soundstage, Bluetooth 5.2.', 379.99, 419.99, 35, '89916f4b-406e-4035-a407-b87d1a582100', 'Marshall', '{"controls": "Bass and treble analogue control knobs, brass volume knob", "power_amps": "One 50 Watt Class D amp for woofer, Two 15 Watt Class D amps for tweeters", "connectivity": "Bluetooth 5.2, 3.5 mm input, RCA input", "frequency_range": "45\u201320,000 Hz"}'::jsonb, ARRAY['marshall', 'speaker', 'audio', 'bluetooth', 'vintage', 'rock', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('231c9dc3-c0a3-4bd0-a3ed-6659a0c91ef2', 'NM-03B09362', 'Bose SoundLink Revolve+ II Portable Bluetooth Speaker - Triple Black', 'bose-soundlink-revolve-ii-portable-bluetooth-speaker-triple-black', 'Deep. Loud. And immersive, too. This true 360° speaker was engineered to spread deep, jaw-dropping sound in every direction. That means, when everyone stands around it, everyone gets the same experience with flexible fabric handle for effortless portability.', 'True 360-degree sound, durable water and dust resistant (IP55), up to 17 hours battery.', 329.00, 359.00, 45, '89916f4b-406e-4035-a407-b87d1a582100', 'Bose', '{"sound": "True 360-degree sound coverage with dual-passive radiators", "durability": "IP55 water- and dust-resistant seamless aluminum body", "battery_life": "Up to 17 hours rechargeable lithium-ion battery", "voice_assistant": "Built-in microphone for speakerphone and Siri / Google Assistant"}'::jsonb, ARRAY['bose', 'speaker', 'soundlink', 'bluetooth', 'portable', '360sound', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('2846645b-c1e8-433e-b97a-b792b6890268', 'NM-5FA0EF17', 'Belkin BoostCharge Pro 3-in-1 Wireless Charging Stand with MagSafe 15W', 'belkin-boostcharge-pro-3-in-1-wireless-charging-stand-with-magsafe-15w', 'Charge your Apple devices faster with this beautifully designed charging stand. Delivering up to 15W of wireless charging to your iPhone 12 or newer, fast charging for Apple Watch Series 7 and later, and a dedicated Qi pad for your AirPods.', 'Official 15W MagSafe fast charging for iPhone, Apple Watch fast charger, and AirPods tray.', 149.95, 169.95, 50, '257cdeb3-d8a0-4866-86d0-23caa424c000', 'Belkin', '{"materials": "Architectural stainless steel arm with soft-touch silicone base", "orientation": "Charge in portrait or landscape for StandBy mode", "compatibility": "Made for MagSafe official 15W certification", "watch_charging": "Apple Watch Fast Charging support"}'::jsonb, ARRAY['belkin', 'magsafe', 'charger', 'apple', 'wireless', 'iphone', 'stand']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('749561a9-1661-4d21-ba8a-9c15dd3ae433', 'NM-4BB27A11', 'Stanley Quencher H2.0 FlowState Stainless Steel Tumbler 40 oz - Rose Quartz', 'stanley-quencher-h2-0-flowstate-stainless-steel-tumbler-40-oz-rose-quartz', 'Constructed of 90% recycled stainless steel for sustainable sipping, the 40 oz Quencher H2.0 helps you reach your hydration goals with fewer refills. Commuting, studio workouts, day trips or your front porch—you''ll want this tumbler by your side.', 'Recycled stainless steel, double-wall vacuum insulation, FlowState 3-position rotating lid.', 45.00, 55.00, 90, 'ba70b78e-1cb9-48d1-a14d-de3ecf4e7331', 'Stanley', '{"lid": "FlowState\u2122 3-position lid (straw opening, drink opening, full cover)", "capacity": "40 oz / 1.18 Liters", "cup_holder": "Car cup holder compatible base", "insulation": "Keeps drinks cold for 11 hours, iced for 2 days"}'::jsonb, ARRAY['stanley', 'quencher', 'tumbler', 'waterbottle', 'hydration', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('ab46416a-4acb-4796-afaa-d361c9385503', 'NM-497CC68B', 'Chemex Classic Eight-Cup Pour-Over Glass Coffeemaker with Wood Collar', 'chemex-classic-eight-cup-pour-over-glass-coffeemaker-with-wood-collar', 'Selected by the Illinois Institute of Technology as one of the 100 best designed products of modern times. The Chemex delivers the purest flavor experience without any chemical residue, producing clean, aromatic pour-over coffee free of sediment and bitterness.', 'Iconic non-porous borosilicate glass carafe with polished wood collar and leather tie.', 49.50, 58.00, 60, 'ba70b78e-1cb9-48d1-a14d-de3ecf4e7331', 'Chemex', '{"design": "Permanent exhibition piece at the Museum of Modern Art (MoMA)", "handle": "Polished wood collar with genuine leather tie", "capacity": "40 oz (8 cups of brewed coffee)", "material": "Heat-resistant non-porous Borosilicate Glass"}'::jsonb, ARRAY['chemex', 'coffee', 'pourover', 'coffeemaker', 'glassware', 'design', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
