INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('daf9c02e-3cc0-4de8-b99b-7013531c08dc', 'NM-E1484FE7', 'Yeti Rambler 20 oz Travel Mug with Stronghold Lid - Navy', 'yeti-rambler-20-oz-travel-mug-with-stronghold-lid-navy', 'This double-duty, on-the-go drinkware is topped with the Rambler® Stronghold™ Lid—a leak-resistant, twist-on upgrade that''s backed with dual-slider magnet technology. This lid easily rotates to fasten for both right- and left-handed users.', '18/8 kitchen-grade stainless steel, double-wall vacuum insulation, leak-resistant twist Stronghold lid.', 38.00, 45.00, 75, 'ba70b78e-1cb9-48d1-a14d-de3ecf4e7331', 'Yeti', '{"lid": "Stronghold\u2122 360-degree twist-on leak-resistant lid", "capacity": "20 fl. oz. / 591 ml", "material": "18/8 Kitchen-grade stainless steel, puncture- and rust-resistant", "cupholder": "Elevated handle fits standard car cup holders"}'::jsonb, ARRAY['yeti', 'rambler', 'travelmug', 'coffee', 'insulated', 'outdoors', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('0cbd7c39-287c-4245-8c78-1420f0d4db90', 'NM-04B881D6', 'Manduka PRO Yoga Mat (6mm High Density Cushion) - Black Sage', 'manduka-pro-yoga-mat-6mm-high-density-cushion-black-sage', 'The #1 recommended mat by yoga teachers worldwide. The Manduka PRO provides unmatched density and joint cushioning on hard floors, proprietary dot-pattern traction, and a lifetime guarantee.', 'Ultra-dense 6mm cushion for joint protection, closed-cell surface prevents sweat absorption.', 138.00, 150.00, 40, 'ba70b78e-1cb9-48d1-a14d-de3ecf4e7331', 'Manduka', '{"surface": "Closed-cell PVC prevents moisture, sweat, and bacteria from entering", "thickness": "6 mm ultra-dense cushioning", "dimensions": "71\" L x 26\" W (180cm x 66cm), Weight: 7.5 lbs", "certification": "STANDARD 100 by OEKO-TEX\u00ae non-toxic emissions manufacturing"}'::jsonb, ARRAY['manduka', 'yogamat', 'yoga', 'fitness', 'pro', 'recovery', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('fa8e22d1-ac28-471d-bb9b-203ac1759dc8', 'NM-553847A2', 'Spalding NBA Official Game Ball Basketball (Full Grain Leather, Size 7)', 'spalding-nba-official-game-ball-basketball-full-grain-leather-size-7', 'Crafted from exclusive Horween full-grain leather that breaks in over time to offer a soft touch and unmatched grip. Meets all stringent professional standards for true bounce and flight consistency.', 'Exclusive Horween full grain leather cover, official NBA 29.5" size, superior bounce and grip.', 129.99, 149.99, 40, 'ba70b78e-1cb9-48d1-a14d-de3ecf4e7331', 'Spalding', '{"use": "Designed strictly for indoor hardwood play", "size": "Official NBA Size 7 (29.5\" circumference)", "cover": "Premium Horween full-grain leather cover", "inflation": "Retains air pressure with butyl bladder and nylon winding"}'::jsonb, ARRAY['spalding', 'basketball', 'nba', 'sports', 'leather', 'athletics', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('d11d301a-2b3a-4bb1-aaa2-70005f05dcea', 'NM-76D2788D', 'Olaplex No. 3 Hair Perfector Repairing Treatment (3.3 fl oz / 100ml)', 'olaplex-no-3-hair-perfector-repairing-treatment-3-3-fl-oz-100ml', 'An at-home bond-building treatment that reduces breakage and visibly strengthens hair, improving its look and feel. Powered by patented OLAPLEX Bond Building Technology™ that repairs broken disulfide bonds caused by heat, chemical processing, and styling.', 'Global bestseller bond-builder reduces breakage and visibly strengthens all hair types.', 30.00, 36.00, 85, '2d6f23b2-6097-4946-85c0-fcb3543a9c20', 'Olaplex', '{"safety": "Paraben-free, phthalate-free, sulfate-free, vegan", "volume": "100 ml / 3.3 fl. oz.", "hair_type": "Straight, Wavy, Curly, and Coily (Color-safe)", "technology": "Bis-Aminopropyl Diglycol Dimaleate patented bond builder"}'::jsonb, ARRAY['olaplex', 'haircare', 'treatment', 'repair', 'beauty', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('1283f5a4-be5c-40b3-bb52-95c541355499', 'NM-20042139', 'Dior Addict Lip Glow Color Reviver Balm - 001 Pink', 'dior-addict-lip-glow-color-reviver-balm-001-pink', 'The 1st Dior lip balm formulated with 97% natural-origin ingredients that subtly revives the natural color of lips with a custom glow for 6h and hydrates lips for 24h. Infused with cherry oil, sunflower wax, and shea butter.', 'Color-awakening hydrating lip balm formulated with 97% natural-origin ingredients and cherry oil.', 40.00, 45.00, 70, 'fdcee139-eca4-4b42-a528-9c2555be59b1', 'Dior', '{"wear": "24h continuous hydration and 6h custom color glow", "shade": "001 Pink (Universal subtle natural flush)", "finish": "Dewy subtle sheen with custom pH color adaptation", "ingredients": "97% Natural-origin with nourishing French cherry oil"}'::jsonb, ARRAY['dior', 'lipglow', 'lipbalm', 'beauty', 'makeup', 'luxury', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('d31d81ce-9fd0-4e52-835d-fdc40171ff1f', 'NM-A33D9379', 'Bellroy Transit Backpack 28L - Black', 'bellroy-transit-backpack-28l-black', 'Clever organization meets sleek minimalist travel. The Transit Backpack features quick-access external pockets for phone, passport, and water bottles, a dedicated lay-flat laptop sleeve, and a spacious main compartment with internal compression straps.', 'Travel carry-on compliant backpack with separate 16" laptop access and hidden passport pocket.', 259.00, 289.00, 35, '990a5535-5d8a-49d1-b6d5-110e526ce641', 'Bellroy', '{"comfort": "Contoured padded breathable mesh back panel with sternum strap", "capacity": "28 Liters (Airline carry-on approved)", "materials": "Durable, water-resistant recycled Baida Nylon fabric with premium leather accents", "laptop_fit": "Fits up to 16\" laptops in padded separate rear compartment"}'::jsonb, ARRAY['bellroy', 'backpack', 'travel', 'carryon', 'minimalist', 'laptopbag', 'bestseller']::varchar[], 0.00, 0, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('0128cd7c-aec2-4025-942d-7231e76201b7', 'NM-86AD7692', 'Lululemon Align High-Rise Pant 25" - Black', 'lululemon-align-high-rise-pant-25-black', 'When feeling nothing is everything. The iconic Align collection, powered by Nulu™ fabric, is so weightless and buttery-soft, all you feel is your practice. Featuring four-way stretch, sweat-wicking performance, and an interior waistband pocket for keys.', 'Buttery-soft, weightless Nulu™ fabric engineered for yoga and low-impact mindful movement.', 98.00, 118.00, 60, '6b69748d-3200-417c-984b-bce91044ccc0', 'Lululemon', '{"feel": "Weightless, buttery-soft second-skin compression", "fabric": "81% Nylon, 19% Lycra\u00ae elastane Nulu\u2122 textile", "waistband": "Seamless lie-flat contour waistband with hidden card pocket", "rise_inseam": "High-Rise fit, 25-inch ankle inseam length"}'::jsonb, ARRAY['lululemon', 'align', 'leggings', 'yoga', 'activewear', 'fitness', 'bestseller']::varchar[], 2.50, 4, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('02bfabe0-1d9f-49aa-a9a2-1452257a1812', 'NM-0B046C98', 'Nintendo Switch OLED Model with White Joy-Con', 'nintendo-switch-oled-model-with-white-joy-con', 'Meet the newest member of the Nintendo Switch family. Play at home on the TV or on-the-go with a vibrant 7-inch OLED screen with the Nintendo Switch (OLED model). In addition to a new screen with vivid colors and sharp contrast, the Nintendo Switch – OLED Model includes a wide adjustable stand for more comfortable viewing angles.', 'Vibrant 7-inch OLED screen, wide adjustable stand, wired LAN dock, 64GB internal storage.', 349.99, 379.99, 90, '257cdeb3-d8a0-4866-86d0-23caa424c000', 'Nintendo', '{"dock": "Includes wired LAN port, HDMI port, 2 USB ports", "modes": "TV mode, Tabletop mode, Handheld mode", "screen": "7.0-inch OLED capacitive multi-touch (1280x720)", "storage": "64GB internal (expandable with microSD up to 2TB)", "battery_life": "Approx. 4.5 to 9 hours"}'::jsonb, ARRAY['nintendo', 'switch', 'gaming', 'console', 'portable', 'bestseller']::varchar[], 4.75, 4, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('041c8c1c-2823-4df1-b076-07eebff97679', 'NM-FDB21AA6', 'Apple Watch Ultra 2 (GPS + Cellular 49mm Titanium Case with Orange Ocean Band)', 'apple-watch-ultra-2-gps-cellular-49mm-titanium-case-with-orange-ocean-band', 'The most rugged and capable Apple Watch ever. Crafted from lightweight corrosion-resistant aerospace titanium with raised sapphire crystal edges, 100m water resistance with EN13319 dive certification, and up to 72 hours of battery life in Low Power Mode.', 'Rugged 49mm aerospace-grade titanium case, 3000-nit display, S9 SiP chip, precision dual-frequency GPS.', 799.00, 849.00, 30, '257cdeb3-d8a0-4866-86d0-23caa424c000', 'Apple', '{"case": "49mm Aerospace-grade Titanium with customizable Action button", "chip": "S9 SiP with 64-bit dual-core processor and Double Tap gesture", "display": "Always-On Retina display with up to 3000 nits peak brightness", "battery_life": "Up to 36 hours normal use; up to 72 hours in Low Power Mode", "water_resistance": "100m water resistant, depth gauge with water temperature sensor"}'::jsonb, ARRAY['apple', 'applewatch', 'ultra2', 'smartwatch', 'fitness', 'titanium', 'bestseller']::varchar[], 3.57, 7, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('1318a3af-4b62-4b25-9c4d-8cb939ab4f91', 'NM-8B1A55A3', 'Dyson V15 Detect Absolute Cordless Stick Vacuum Cleaner', 'dyson-v15-detect-absolute-cordless-stick-vacuum-cleaner', 'Dyson''s most intelligent cordless vacuum. A precisely-angled laser illuminates invisible dust on hard floors. An acoustic piezo sensor continuously sizes and counts dust particles, automatically increasing suction power when higher volumes of debris are detected. The LCD screen shows real-time scientific proof of a deep clean.', 'Laser reveals invisible dust, piezo sensor measures dust particles, 240AW powerful suction.', 749.99, 849.99, 35, '815ef732-5845-4b00-bdf9-7af219e7835d', 'Dyson', '{"weight": "3.1 kg (6.8 lbs)", "run_time": "Up to 60 minutes fade-free power", "bin_volume": "0.2 Gallons (0.77 Liters) with point-and-shoot hygienic emptying", "filtration": "Whole-machine advanced HEPA filtration (traps 99.99% of particles down to 0.1 microns)", "suction_power": "240 Air Watts with Dyson Hyperdymium\u2122 motor (125,000 RPM)"}'::jsonb, ARRAY['dyson', 'vacuum', 'cleaning', 'cordless', 'laser', 'home', 'bestseller']::varchar[], 2.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('16f898f3-4124-42a7-ab8e-80682847012c', 'NM-C2F1D49A', 'Theragun PRO Plus Multi-Therapy Percussive Massage Device', 'theragun-pro-plus-multi-therapy-percussive-massage-device', 'The ultimate recovery device. Theragun PRO Plus combines deep tissue percussive therapy with near-infrared LED light therapy, vibration therapy, and thermal therapy. Scientifically proven to relieve pain, optimize mobility, and accelerate muscle recovery for world-class athletes and active individuals.', 'Deep 16mm percussive therapy, near-infrared LED light therapy, vibration therapy, biometric sensor.', 599.00, 649.00, 35, '6b69748d-3200-417c-984b-bce91044ccc0', 'Therabody', '{"screen": "Full-color LCD with guided visual routines and biometric heart rate display", "amplitude": "16mm percussive depth reaches 60% deeper into muscle", "therapies": "Percussive therapy, Near-infrared LED light, Heat therapy, Cold therapy compatible, Breathwork", "stall_force": "Up to 60 lbs of no-stall force"}'::jsonb, ARRAY['theragun', 'therabody', 'massage', 'recovery', 'fitness', 'therapy', 'pro']::varchar[], 4.33, 3, True, False) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('1e95a157-6d29-4e31-a790-0d3c198edadb', 'NM-81DE3FC7', 'Le Labo Santal 33 Eau de Parfum (100ml)', 'le-labo-santal-33-eau-de-parfum-100ml', 'A perfume that touches the sensual universality of this icon, which would intoxicate a man as much as a woman. It introduces Le Labo''s use of cardamom, iris, violet, and ambrox which crackle in the formula and bring to this smoking wood alloy (Australian sandalwood, cedarwood) spicy, leathery, and musky notes.', 'Hypnotic scent of the American West featuring Australian sandalwood, cedarwood, cardamom, and leather.', 320.00, 340.00, 35, 'c1406032-d9d2-4c5c-9a0c-ac67b90c1b3c', 'Le Labo', '{"volume": "100 ml / 3.4 fl. oz.", "ethical": "Cruelty-free, paraben-free, 100% vegan", "profile": "Woody, Aromatic, Spicy Leather", "concentration": "Eau de Parfum (Hand-formulated)"}'::jsonb, ARRAY['lelabo', 'santal33', 'fragrance', 'perfume', 'niche', 'artisanal', 'bestseller']::varchar[], 3.50, 4, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('266297e4-eca5-4e5e-b560-2ba7fbcc410f', 'NM-8A397E88', 'Augustinus Bader The Rich Cream with TFC8® (50ml)', 'augustinus-bader-the-rich-cream-with-tfc8-r-50ml', 'Backed by 30 years of research by biomedical scientist Professor Augustinus Bader. The Rich Cream is an intensely luxurious moisturizer that deeply hydrates, reduces fine lines and wrinkles, and visibly promotes cellular renewal with evening primrose, argan, and avocado oils.', 'Award-winning cellular renewal daily moisturizer powered by biomedical TFC8® technology.', 290.00, 310.00, 40, 'fdcee139-eca4-4b42-a528-9c2555be59b1', 'Augustinus Bader', '{"volume": "50 ml / 1.7 fl. oz. recyclable glass pump", "formula": "100% vegan, cruelty-free, fragrance-free", "skin_type": "Ideal for normal to dry skin, mature skin, and dry winter climates", "active_technology": "Trigger Factor Complex 8 (TFC8\u00ae) amino acids, vitamins, and synthesized molecules"}'::jsonb, ARRAY['augustinusbader', 'skincare', 'richcream', 'luxury', 'antiaging', 'cleanbeauty', 'bestseller']::varchar[], 3.88, 8, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('2b9bfea1-72ca-4e12-bf4c-5be1900ce6b6', 'NM-9C6E5B27', 'Apple MacBook Pro 16" (M3 Max, 36GB Unified Memory, 1TB SSD) - Space Black', 'apple-macbook-pro-16-m3-max-36gb-unified-memory-1tb-ssd-space-black', 'The 16-inch MacBook Pro blasts forward with M3 Max, an extraordinarily advanced chip that brings massive performance and capabilities for the most extreme workflows. Built with 3-nanometer technology and featuring an all-new GPU architecture, it''s the most advanced chip ever built for a personal computer. With industry-leading battery life — up to 22 hours — and a breathtaking Liquid Retina XDR display, it''s a pro laptop without equal.', 'Liquid Retina XDR display, M3 Max chip with 16-core CPU, up to 22 hours of battery life.', 3499.00, 3799.00, 45, '47734feb-7f89-4f3a-abd0-52f7d03d0016', 'Apple', '{"ram": "36GB Unified Memory", "ports": "3x Thunderbolt 4, HDMI, SDXC card slot, MagSafe 3", "weight": "2.16 kg (4.8 lbs)", "display": "16.2-inch Liquid Retina XDR (3456x2234, 120Hz ProMotion)", "storage": "1TB Superfast NVMe SSD", "processor": "Apple M3 Max (16-core CPU, 40-core GPU)", "battery_life": "Up to 22 hours"}'::jsonb, ARRAY['apple', 'macbook', 'laptop', 'm3', 'pro', 'bestseller', 'premium']::varchar[], 3.80, 5, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('2f84b185-6c34-4d6a-b90f-f7697f6d822c', 'NM-1F8B19A7', 'Saint Laurent SL 557 Shade Bold Acetate Sunglasses', 'saint-laurent-sl-557-shade-bold-acetate-sunglasses', 'Infuse sleek Parisian edge into every look. These statement rectangular frames are carved from thick glossy black Italian acetate, featuring silver corner rivets and laser-engraved Saint Laurent signature branding along the wide temple arms.', 'Narrow rectangular thick acetate sunglasses with bevelled temples and 100% UVA/UVB mineral lenses.', 495.00, 530.00, 40, '92292d4b-f991-4511-93bd-4f83e8672c60', 'Saint Laurent', '{"case": "Includes magnetic Saint Laurent leather case and cloth", "frame": "100% Premium Gloss Italian Acetate", "lenses": "100% UVA/UVB Category 3 Mineral Glass lenses", "dimensions": "Lens 53mm, Bridge 20mm, Temple 145mm"}'::jsonb, ARRAY['saintlaurent', 'sunglasses', 'eyewear', 'acetate', 'luxury', 'black']::varchar[], 4.00, 5, True, False) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('31b9e886-cc41-4a10-a246-e4b2b97ce004', 'NM-40044931', 'Nespresso VertuoPlus Deluxe Coffee and Espresso Machine by De''Longhi', 'nespresso-vertuoplus-deluxe-coffee-and-espresso-machine-by-de-longhi', 'Nespresso VertuoPlus offers freshly brewed coffee with crema as well as delicious, authentic espresso. Designed for Nespresso Vertuo capsules only, with smart barcode recognition technology that adjusts brewing parameters automatically for each unique blend.', 'Centrifusion extraction technology, single-touch brewing, 5 cup sizes from espresso to alto.', 199.00, 229.00, 60, '46d63413-c0ad-4c4b-b437-b73f21ff17f2', 'Nespresso', '{"cup_sizes": "Espresso (1.35oz), Double Espresso (2.7oz), Gran Lungo (5oz), Coffee (7.7oz), Alto (14oz)", "technology": "Centrifusion\u2122 technology (7,000 RPM capsule spinning)", "water_tank": "60 oz extra-large movable water reservoir", "heat_up_time": "Fast 20-second preheating"}'::jsonb, ARRAY['nespresso', 'coffee', 'espresso', 'latte', 'kitchen', 'delonghi', 'bestseller']::varchar[], 3.75, 8, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('3945237f-a9ca-4f1b-a806-d56afd2e1718', 'NM-283FB673', 'Apple AirPods Pro (2nd Generation) with MagSafe Case (USB-C)', 'apple-airpods-pro-2nd-generation-with-magsafe-case-usb-c', 'AirPods Pro (2nd generation) with USB-C deliver up to 2x more Active Noise Cancellation than the previous generation, with Transparency mode that enables you to hear the world around you, and all-new Adaptive Audio that dynamically tailors noise control to your environment.', 'Up to 2x more Active Noise Cancellation, Adaptive Audio, Transparency mode, Personalized Spatial Audio.', 249.00, 279.00, 110, '89916f4b-406e-4035-a407-b87d1a582100', 'Apple', '{"chip": "Apple H2 headphone chip, Apple U1 chip in case", "charging": "USB-C, MagSafe, Apple Watch charger, Qi-certified", "features": "Personalized Spatial Audio with dynamic head tracking", "battery_life": "Up to 6 hours (single charge), up to 30 hours with case", "water_resistance": "IP54 dust, sweat, and water resistant"}'::jsonb, ARRAY['apple', 'airpods', 'earbuds', 'anc', 'wireless', 'bestseller']::varchar[], 3.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('45d089e3-1c08-41fc-af29-ebd639ac5407', 'NM-5EAEAD6A', 'Sony WH-1000XM5 Wireless Industry-Leading Noise-Canceling Headphones - Silver', 'sony-wh-1000xm5-wireless-industry-leading-noise-canceling-headphones-silver', 'Sony''s flagship noise-canceling headphones rewrite the rules for distraction-free listening. Featuring two processors controlling eight microphones, an Auto NC Optimizer for automatically calibrating noise cancellation based on wearing conditions and atmospheric pressure, and an ultra-comfortable lightweight design.', 'Auto NC Optimizer, two processors, 8 microphones, 30-hour battery, and LDAC Hi-Res Wireless.', 399.99, 449.99, 50, '89916f4b-406e-4035-a407-b87d1a582100', 'Sony', '{"driver_unit": "30mm precision-engineered Carbon Fiber composite driver", "battery_life": "30 hours with ANC turned on; 3 min quick-charge gives 3 hours playback", "connectivity": "Bluetooth 5.2 with Multipoint connection, LDAC Hi-Res Audio, 3.5mm wired", "noise_canceling": "Integrated Processor V1 + HD Noise Canceling Processor QN1"}'::jsonb, ARRAY['sony', 'headphones', 'noisecanceling', 'bluetooth', 'audio', 'premium', 'bestseller']::varchar[], 4.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('472e760a-2d06-4960-87d1-98c129dc6f9a', 'NM-9A50341B', 'Sony WH-1000XM5 Wireless Industry Leading Noise Canceling Headphones - Black', 'sony-wh-1000xm5-wireless-industry-leading-noise-canceling-headphones-black', 'The WH-1000XM5 headphones rewrite the rules for distraction-free listening. Two processors control 8 microphones for unprecedented noise cancellation and exceptional call quality. With a newly developed driver, DSEE - Extreme and Hi-Res audio support, these headphones provide awe-inspiring audio quality without compromise.', 'Auto NC Optimizer with 8 microphones, up to 30 hours battery, ultra-comfortable lightweight design.', 398.00, 449.00, 80, '89916f4b-406e-4035-a407-b87d1a582100', 'Sony', '{"anc": "Industry-leading Active Noise Cancellation with V1 & QN1 processors", "codecs": "LDAC, AAC, SBC", "weight": "250 grams", "microphones": "8 microphones with AI beamforming", "battery_life": "Up to 30 hours (ANC on), 40 hours (ANC off)", "quick_charge": "3 minutes gives 3 hours playback"}'::jsonb, ARRAY['sony', 'headphones', 'anc', 'wireless', 'audiophile', 'bestseller']::varchar[], 3.75, 4, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('525f6e7f-2c41-4fd1-b433-d1320c84baf7', 'NM-BDDA171F', 'Dyson Airwrap Multi-Styler Complete Long - Strawberry Bronze and Blush Pink', 'dyson-airwrap-multi-styler-complete-long-strawberry-bronze-and-blush-pink', 'Curl, wave, smooth, and dry with no extreme heat. The Dyson Airwrap utilizes an aerodynamic phenomenon known as the Coanda effect, curving air to attract and wrap hair around the barrel using only air and controlled heat.', 'Coanda airflow technology styles hair without extreme heat damage; engineered for long hair.', 599.99, 649.99, 25, '2d6f23b2-6097-4946-85c0-fcb3543a9c20', 'Dyson', '{"motor": "Dyson digital motor V9 spinning at 110,000 rpm", "attachments": "Includes 6 re-engineered styling attachments and travel pouch", "hair_length": "Optimized for hair that''s chest-length or longer", "heat_control": "Intelligent glass bead thermistor measuring air temperature 40 times a second"}'::jsonb, ARRAY['dyson', 'airwrap', 'hairstyling', 'beauty', 'haircare', 'luxury', 'bestseller']::varchar[], 2.20, 5, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('58b51deb-d29f-457e-92a0-bdbf21ee0b2b', 'NM-7DB5CB93', 'The North Face 1996 Retro Nuptse 700-Fill Down Jacket - TNF Black', 'the-north-face-1996-retro-nuptse-700-fill-down-jacket-tnf-black', 'Built for mountain- and city-life, the 1996 Retro Nuptse Jacket has an unmistakable silhouette. With its water-repellent ripstop fabric and oversized baffles filled with ultra-warm 700-fill goose down, it keeps you warm and dry when temperatures plunge.', '700-fill goose down insulation, durable water-repellent (DWR) finish, packable hood.', 330.00, 360.00, 45, '93aaef76-ddb4-4530-a43d-23e489a6c969', 'The North Face', '{"fit": "Relaxed boxy silhouette", "hood": "Stows in collar", "fabric": "40D 54 g/m\u00b2 100% recycled nylon ripstop with non-PFC DWR finish", "insulation": "700-fill goose down certified to the Responsible Down Standard (RDS)", "packability": "Stows in right hand pocket"}'::jsonb, ARRAY['thenorthface', 'jacket', 'winter', 'puffer', 'outerwear', 'streetwear', 'bestseller']::varchar[], 4.12, 8, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('5f5e750c-d6c9-419d-abd3-3b9408dca81c', 'NM-D3611E19', 'Burberry The Pimlico Heritage Car Coat - Honey', 'burberry-the-pimlico-heritage-car-coat-honey', 'The Car Coat is a versatile, single-breasted style rooted in our motoring heritage. Light and protective, it is made in Castleford, Yorkshire from signature weatherproof cotton gabardine and lined in archival Vintage check — a print first used in the 1960s. The Pimlico fit is softly tailored with a straight cut that slips easily over tailored layers.', 'Single-breasted cotton gabardine car coat tailored with clean raglan sleeves and Vintage check lining.', 1790.00, 1950.00, 20, '93aaef76-ddb4-4530-a43d-23e489a6c969', 'Burberry', '{"fit": "Pimlico tailored fit", "lining": "100% Cotton Vintage Check Lining", "origin": "Made in England", "closure": "Concealed button placket, horn buttons", "material": "100% Weatherproof Cotton Gabardine"}'::jsonb, ARRAY['burberry', 'coat', 'trench', 'heritage', 'luxury', 'outerwear', 'bestseller']::varchar[], 2.50, 2, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('61beb5e5-d196-4c6f-937b-9f074d16128c', 'NM-886181F1', 'Instant Pot Duo Plus 9-in-1 Multi-Cooker (6 Quart)', 'instant-pot-duo-plus-9-in-1-multi-cooker-6-quart', 'The Instant Pot Duo Plus 9-in-1 is an upgrade to America''s #1 most-loved multi-cooker. Easy to use, easy to clean, versatile and convenient. The improved easy-release steam switch makes venting steam simple, fast, and whisper-quiet. Cook delicious meals up to 70% faster than traditional methods.', 'Pressure cooker, slow cooker, rice cooker, yogurt maker, steamer, sauté pan, sous vide, and food warmer.', 129.95, 149.95, 95, '46d63413-c0ad-4c4b-b437-b73f21ff17f2', 'Instant Pot', '{"power": "1000 Watts", "safety": "Over 10 proven safety features including Overheat Protection\u2122", "capacity": "6 Quart (serves up to 6 people)", "functions": "9-in-1 (Pressure, Slow Cook, Rice, Yogurt, Steam, Saut\u00e9, Sous Vide, Sterilize, Warm)", "inner_pot": "Food-grade 18/8 stainless steel cooking pot with tri-ply bottom"}'::jsonb, ARRAY['instantpot', 'kitchen', 'cooker', 'appliance', 'sousvide', 'bestseller']::varchar[], 3.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('694f4436-a5fa-4b4b-a00e-625904c855e2', 'NM-A9F70F6B', 'Apple Watch Series 9 GPS 45mm (Midnight Aluminum Case with Sport Band)', 'apple-watch-series-9-gps-45mm-midnight-aluminum-case-with-sport-band', 'Smarter. Brighter. Mightier. Apple Watch Series 9 helps you stay connected, active, healthy, and safe. Featuring double tap, a magical way to interact with Apple Watch without touching the screen, an even brighter display, and Precision Finding for iPhone.', 'S9 SiP chip, Double Tap gesture control, brighter 2000-nit display, ECG and Blood Oxygen apps.', 429.00, 459.00, 70, '257cdeb3-d8a0-4866-86d0-23caa424c000', 'Apple', '{"chip": "S9 SiP with 64-bit dual-core processor, 4-core Neural Engine", "battery": "18 hours normal use, up to 36 hours in Low Power Mode", "display": "Always-On Retina OLED (up to 2000 nits, down to 1 nit)", "health_sensors": "Blood Oxygen, ECG, Temperature sensing, Heart Rate", "water_resistance": "50m swimproof (WR50)"}'::jsonb, ARRAY['apple', 'watch', 'smartwatch', 'fitness', 'health', 'bestseller']::varchar[], 4.00, 2, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('6e7f7076-d324-4d71-a1d9-764fbb5274bb', 'NM-D3C18609', 'Totême Signature Wool-Cashmere Blend Double Coat', 'toteme-signature-wool-cashmere-blend-double-coat', 'A Scandinavian masterclass in minimalist proportion. Cut from an exceptionally soft blend of certified wool and cashmere, this double-breasted wrap coat features generous dropped shoulders, deep patch pockets, and a clean belted waist.', 'Oversized wrap silhouette woven from heavyweight brushed wool and cashmere with draped lapels.', 1280.00, 1400.00, 18, '93aaef76-ddb4-4530-a43d-23e489a6c969', 'Totême', '{"fit": "Signature relaxed, oversized silhouette", "care": "Dry clean only", "color": "Oatmeal Melange", "composition": "90% Certified Wool, 10% Cashmere"}'::jsonb, ARRAY['toteme', 'coat', 'wool', 'cashmere', 'minimalist', 'scandinavian', 'quietluxury']::varchar[], 3.67, 3, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('6f2128a5-53be-4458-ba23-9cf84018240f', 'NM-6C681F9A', 'Dyson V15 Detect Absolute Cordless Stick Vacuum', 'dyson-v15-detect-absolute-cordless-stick-vacuum', 'Dyson''s most intelligent cordless vacuum. Features a laser slim Fluffy cleaner head that reveals microscopic dust on hard floors, an acoustic piezo sensor that continuously sizes and counts particles, automatically adjusting suction power according to debris volume.', 'Illuminating green laser Reveals invisible dust, piezo sensor measures particle count, 230AW suction.', 749.99, 849.99, 35, '815ef732-5845-4b00-bdf9-7af219e7835d', 'Dyson', '{"run_time": "Up to 60 minutes fade-free click-in battery", "filtration": "Whole-machine HEPA filtration traps 99.99% of particles down to 0.1 microns", "bin_capacity": "0.76 Liters with hygienic point-and-shoot emptying", "suction_power": "230 Air Watts (Hyperdymium motor spinning up to 125,000 rpm)"}'::jsonb, ARRAY['dyson', 'vacuum', 'cleaning', 'home', 'smart', 'laser', 'bestseller']::varchar[], 5.00, 2, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('75949c56-32df-43a2-b2c6-6666ee72fce2', 'NM-C2AE35D0', 'Loro Piana Summer Charms Walk Suede Loafers', 'loro-piana-summer-charms-walk-suede-loafers', 'The quintessential quiet luxury footwear: handcrafted from unlined velvety calfskin suede treated with a water-repellent and stain-resistant finish. Complete with lightweight white latex soles and engraved metal charms resting across the front strap.', 'Water-repellent unlined suede loafers adorned with mini padlock and charm hardware.', 1050.00, 1150.00, 25, '9eb42450-bb43-4b3c-8bb4-c8da95064d72', 'Loro Piana', '{"sole": "Lightweight non-slip natural latex rubber", "origin": "Handmade in Italy", "material": "100% Unlined Calf Suede with water-repellent treatment", "detailing": "Engraved mini padlock and key charms"}'::jsonb, ARRAY['loropiana', 'loafers', 'suede', 'quietluxury', 'luxury', 'footwear', 'italian']::varchar[], 4.17, 6, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('783d2f7f-4e34-4b04-bae5-a06e50c83cff', 'NM-FE976754', 'Arc''teryx Beta AR Gore-Tex Pro Waterproof Shell Jacket - Black', 'arc-teryx-beta-ar-gore-tex-pro-waterproof-shell-jacket-black', 'Packable, breathable, durable waterproof protection across the spectrum of alpine environments and activities. The Beta AR Jacket is engineered with GORE-TEX PRO with Most Rugged Technology — a next-generation material developed in collaboration with Gore.', 'Most Rugged 3-layer GORE-TEX PRO waterproof jacket with helmet-compatible DropHood™.', 600.00, 650.00, 30, '978fe759-ed24-4dc0-85c9-48e57599d513', 'Arc''teryx', '{"hood": "Helmet-compatible DropHood\u2122 with Cohaesive\u2122 cord locks", "recco": "Integrated RECCO\u00ae reflector for search and rescue location", "fabric": "N40d 3L GORE-TEX PRO with ultra-durable N80d reinforcements", "zippers": "WaterTight\u2122 external zippers and pit zips for rapid ventilation"}'::jsonb, ARRAY['arcteryx', 'goretex', 'jacket', 'waterproof', 'alpine', 'outdoor', 'bestseller']::varchar[], 3.75, 4, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('798a6613-2ae8-45b4-8eba-4c61d6ee1402', 'NM-0E52306D', 'On Cloudmonster 2 Max-Cushion Road Running Shoes - Undyed White', 'on-cloudmonster-2-max-cushion-road-running-shoes-undyed-white', 'Maximum energy return with monstrous cushioning. The Cloudmonster 2 brings On''s biggest Cloud elements ever, combined with an ultra-responsive nylon blend Speedboard® to propel you forward on long recovery runs and tempo sessions alike.', 'Extreme CloudTec® cushioning with dual-density Helion™ superfoam and nylon Speedboard®.', 179.99, 190.00, 45, '764547b9-9b3c-4717-9110-361a937c90a0', 'On Running', '{"drop": "6 mm heel-to-toe drop", "weight": "295 g (10.4 oz)", "cushioning": "Max-Cushion CloudTec\u00ae with dual-density Helion\u2122 superfoam", "sustainability": "100% recycled polyester engineered mesh upper"}'::jsonb, ARRAY['onrunning', 'cloudmonster', 'runningshoes', 'sneakers', 'marathon', 'fitness', 'bestseller']::varchar[], 2.83, 6, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('7ab2bd4c-fb86-42d1-8a16-7e46b7fe381a', 'NM-26C5BDEB', 'Samsung Galaxy S24 Ultra 5G (512GB, Titanium Gray) with Galaxy AI & S-Pen', 'samsung-galaxy-s24-ultra-5g-512gb-titanium-gray-with-galaxy-ai-s-pen', 'Meet Galaxy S24 Ultra, the ultimate form of Galaxy Ultra with a new titanium exterior and a 6.8-inch flat display. Unleash whole new levels of creativity, productivity, and possibility starting with the most important device in your life — your phone. Search like never before with Circle to Search, get real-time voice translation on a call, and format your notes into a clear summary.', 'Galaxy AI, 200MP camera system, Snapdragon 8 Gen 3 for Galaxy, built-in S Pen.', 1299.99, 1419.99, 50, 'b0cedd18-d2ea-4745-9ff6-26099432e969', 'Samsung', '{"ram": "12GB RAM", "camera": "200MP Wide + 50MP 5x Periscope + 10MP 3x Telephoto + 12MP Ultra-wide", "battery": "5000mAh with 45W wired charging", "display": "6.8\" Dynamic LTPO AMOLED 2X (1-120Hz, 2600 nits)", "storage": "512GB UFS 4.0", "processor": "Snapdragon 8 Gen 3 for Galaxy"}'::jsonb, ARRAY['samsung', 'galaxy', 's24', 'android', 'ai', 'spen', 'bestseller']::varchar[], 3.25, 4, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('7ce6f346-c7b3-4f28-9b05-461128efb30f', 'NM-D5714093', 'Apple iPad Pro 12.9" (M2, Wi-Fi, 256GB) - Space Gray', 'apple-ipad-pro-12-9-m2-wi-fi-256gb-space-gray', 'iPad Pro. With mind-blowing performance from the M2 chip, superfast wireless connectivity, and next-generation Apple Pencil experience. Plus powerful productivity features in iPadOS. It''s the ultimate iPad experience.', 'Liquid Retina XDR display with Mini-LED backlighting, M2 chip, Apple Pencil hover.', 1099.00, 1199.00, 40, 'b0cedd18-d2ea-4745-9ff6-26099432e969', 'Apple', '{"audio": "Four speaker audio and five studio-quality microphones", "cameras": "12MP Wide and 10MP Ultra Wide back cameras, LiDAR Scanner", "display": "12.9\" Liquid Retina XDR Mini-LED (2732x2048, 1000 nits)", "storage": "256GB", "processor": "Apple M2 Chip (8-core CPU, 10-core GPU)"}'::jsonb, ARRAY['apple', 'ipad', 'tablet', 'm2', 'retina', 'drawing']::varchar[], 1.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('7e31bf3d-77a0-4882-9799-322ee4549fce', 'NM-8575D9F1', 'Le Creuset Enameled Cast Iron Round Dutch Oven (5.5 Qt, Cerise Red)', 'le-creuset-enameled-cast-iron-round-dutch-oven-5-5-qt-cerise-red', 'An indispensable heirloom culinary classic. Individually cast in sand molds and hand-inspected by French artisans since 1925, Le Creuset''s iconic Dutch oven delivers peerless heat distribution and moisture retention for slow-cooking, braising, baking sourdough, and searing.', 'Iconic French enameled cast iron Dutch oven with sand-colored interior and stainless steel knob.', 420.00, 460.00, 30, '0ea5506e-5de0-47e0-886c-ee6f112fe699', 'Le Creuset', '{"origin": "Handcrafted in Fresnoy-le-Grand, France", "capacity": "5.5 Quarts (Serves 5\u20136)", "material": "Enameled Cast Iron, chip-resistant vibrant porcelain enamel", "heat_rating": "Oven safe up to 500\u00b0F (260\u00b0C)", "cooktop_compatibility": "Induction, Gas, Electric, Ceramic, Halogen"}'::jsonb, ARRAY['lecreuset', 'cookware', 'dutchoven', 'castiron', 'gourmet', 'kitchen', 'bestseller']::varchar[], 2.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('82104181-1ad0-4161-8ac1-e59535513bc3', 'NM-82F557B5', 'Yeti Tundra 45 Hard Cooler - Desert Tan', 'yeti-tundra-45-hard-cooler-desert-tan', 'The YETI Tundra 45 combines versatility with legendary durability. Infused with that legendary YETI toughness — a durable rotomolded construction and up to three inches of PermaFrost™ Insulation. Which is all to say it''s built to last and will keep your contents ice-cold even in sweltering triple-digit heat.', 'Rotomolded construction, PermaFrost 3-inch pressure-injected insulation, bear-resistant certification.', 325.00, 350.00, 40, '978fe759-ed24-4dc0-85c9-48e57599d513', 'Yeti', '{"capacity": "Holds up to 28 cans with recommended 2:1 ice-to-contents ratio", "dimensions": "25 3/4\" L x 16 1/8\" W x 15 3/8\" H", "insulation": "Up to 3 inches of commercial-grade PermaFrost\u2122 polyurethane foam", "construction": "FatWall\u2122 design rotomolded polyethylene (virtually indestructible)", "empty_weight": "23 lbs (10.4 kg)"}'::jsonb, ARRAY['yeti', 'cooler', 'camping', 'outdoors', 'adventure', 'icecold', 'bestseller']::varchar[], 4.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('83fa9be0-3feb-4439-9a2c-d9929edff31d', 'NM-B224C48C', 'Le Creuset Enameled Cast Iron Signature Round Dutch Oven (5.5 Quart, Cerise Red)', 'le-creuset-enameled-cast-iron-signature-round-dutch-oven-5-5-quart-cerise-red', 'An iconic culinary classic, the Le Creuset Round Dutch Oven is indispensable in the kitchens of home cooks and professional chefs alike. Expertly crafted from enameled cast iron, the everyday versatility of the Dutch oven makes it ideal for everything from slow-cooking and braising to roasting, baking, frying and more.', 'Handcrafted in France since 1925, superior heat distribution and retention, chip-resistant enamel.', 420.00, 460.00, 30, '0ea5506e-5de0-47e0-886c-ee6f112fe699', 'Le Creuset', '{"origin": "Handcrafted in Fresnoy-le-Grand, France", "capacity": "5.5 Quart (serves 5-6)", "cleaning": "Dishwasher safe", "material": "Vibrant exterior enamel resists chipping and cracking; sand-colored interior enamel promotes caramelization", "compatibility": "Induction, Gas, Electric, Ceramic, Halogen, Oven safe up to 500\u00b0F"}'::jsonb, ARRAY['lecreuset', 'cookware', 'dutchoven', 'castiron', 'cooking', 'french', 'luxury']::varchar[], 3.00, 1, True, False) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('85b4cb4b-b379-4011-ab52-186e04bdbb72', 'NM-90F5AF26', 'Levi''s 501 Original Fit Straight Leg Selvedge Denim Jeans', 'levi-s-501-original-fit-straight-leg-selvedge-denim-jeans', 'Close your eyes. Think “jeans.” Now open. They were 501s, right? With a classic straight leg and iconic styling, they''re literally the blueprint for every pair of jeans in existence — burned into the world''s collective cortex ever since Levi Strauss invented them in 1873.', 'The original straight fit jean since 1873, iconic signature button fly, 100% non-stretch cotton denim.', 98.00, 118.00, 85, '6f5a8e29-f363-43b7-a9fe-04d23add0fd1', 'Levi''s', '{"fit": "Regular through the thigh with straight leg opening", "fly": "Signature metal button fly", "wash": "Medium Indigo Stone Wash", "fabric": "100% Cotton heavy-duty denim"}'::jsonb, ARRAY['levis', 'jeans', 'denim', 'classic', 'vintage', '501', 'bestseller']::varchar[], 5.00, 2, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('8d958dcb-85f3-4479-93a5-f5c5a3f7a514', 'NM-50BD8ED5', 'Herman Miller Aeron Ergonomic Office Chair (Size B, Graphite, PostureFit SL)', 'herman-miller-aeron-ergonomic-office-chair-size-b-graphite-posturefit-sl', 'The gold standard of ergonomic seating. Designed by Bill Stumpf and Don Chadwick, the Aeron chair distributes weight evenly across 8 variable tension zones, eliminating pressure points and keeping your body cool and comfortable through intensive 10+ hour work days.', 'Pellicle 8Z breathable suspension mesh, dual PostureFit SL sacral support, and fully adjustable arms.', 1725.00, 1895.00, 22, '504946a3-4582-40f9-a4c7-a0f7a03f21fe', 'Herman Miller', '{"arms": "Fully adjustable 4D armrests (height, depth, and pivot)", "size": "Medium (Size B, accommodates 5''2\" to 6''2\" users)", "tilt": "Forward tilt (5\u00b0) and tilt limiter with tension control", "support": "PostureFit SL adjustable sacral and lumbar pads", "warranty": "12-Year Herman Miller 24/7 use manufacturer warranty"}'::jsonb, ARRAY['hermanmiller', 'aeron', 'officechair', 'ergonomic', 'furniture', 'luxury', 'homeoffice']::varchar[], 2.50, 2, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('909beaf5-d233-430a-ba22-bdc29acddae4', 'NM-BB2D6CB3', 'Nike Air Force 1 ''07 All-White Classic Leather Sneakers', 'nike-air-force-1-07-all-white-classic-leather-sneakers', 'The radiance lives on in the Nike Air Force 1 ''07, the b-ball icon that puts a fresh spin on what you know best: crisp leather, bold colors and the perfect amount of flash to make you shine. Stitched overlays on the upper add heritage style, durability and support, while Nike Air cushioning adds lightweight, all-day comfort.', 'Crisp leather edges, stitched overlays, heritage Nike Air cushioning, timeless low-cut design.', 115.00, 130.00, 120, '9eb42450-bb43-4b3c-8bb4-c8da95064d72', 'Nike', '{"upper": "100% Genuine Full-Grain Leather", "closure": "Lace-up with metallic AF-1 dubrae", "midsole": "Nike Air encapsulated cushioning unit", "outsole": "Non-marking solid rubber with pivot circles", "colorway": "Triple White (White/White)"}'::jsonb, ARRAY['nike', 'airforce', 'sneakers', 'shoes', 'streetwear', 'classic', 'bestseller']::varchar[], 3.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('9acbc2dd-e50d-416d-a1a1-f8a28d707d53', 'NM-6AF8107D', 'Fellow Stagg EKG Electric Pour-Over Kettle - Matte Black', 'fellow-stagg-ekg-electric-pour-over-kettle-matte-black', 'Elevate your morning ritual. Whether you''re a seasoned barista or a coffee enthusiast, the Fellow Stagg EKG combines aesthetic perfection with surgical pouring control. Featuring a 1200W quick-heating element, full PID temperature regulation from 135°F to 212°F, and a 60-minute temperature hold mode.', 'Precision gooseneck spout, to-the-degree PID temperature control, and built-in brew stopwatch.', 195.00, 220.00, 50, '46d63413-c0ad-4c4b-b437-b73f21ff17f2', 'Fellow', '{"power": "1200W, 120V fast-boil heating system", "spout": "Counterbalanced precision gooseneck pour spout", "volume": "0.9 Liters (30 oz)", "display": "High-contrast discreet LCD showing target and live temperatures"}'::jsonb, ARRAY['fellow', 'kettle', 'pourover', 'coffee', 'design', 'kitchen', 'bestseller']::varchar[], 4.25, 4, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('9f657211-16e9-4c61-8535-01a123a90b23', 'NM-75843100', 'Patagonia Better Sweater 1/4-Zip Fleece Jacket - Stonewash', 'patagonia-better-sweater-1-4-zip-fleece-jacket-stonewash', 'A warm, low-bulk quarter-zip pullover made with soft, ribbed-knit 100% recycled polyester fleece. Dyed with a low-impact process that significantly reduces the use of dyestuffs, energy and water compared to conventional dyeing methods.', '100% recycled polyester sweater-knit fleece dyed with low-impact process, Fair Trade Certified sewn.', 139.00, 159.00, 60, '93aaef76-ddb4-4530-a43d-23e489a6c969', 'Patagonia', '{"pocket": "Zippered left-chest pocket", "features": "Quarter-zip with zip-through stand-up collar", "material": "10-oz 100% recycled polyester knit fleece", "certifications": "Fair Trade Certified\u2122 sewn, bluesign\u00ae approved fabric"}'::jsonb, ARRAY['patagonia', 'fleece', 'jacket', 'sustainable', 'outdoors', 'bestseller']::varchar[], 4.67, 3, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('a1120670-8549-4d8f-a446-1525dfc0fa87', 'NM-CE87111E', 'Maison Francis Kurkdjian Baccarat Rouge 540 Eau de Parfum (70ml)', 'maison-francis-kurkdjian-baccarat-rouge-540-eau-de-parfum-70ml', 'An intoxicating, iconic signature fragrance born of the encounter between Maison Francis Kurkdjian and Baccarat to celebrate the crystal manufacturer''s 250th birthday. Luminous and sophisticated, Baccarat Rouge 540 lays on the skin like an amber, floral, and woody breeze.', 'Luminous amber, floral, and woody breeze with jasmine, saffron, cedarwood, and ambergris.', 325.00, 350.00, 30, 'c1406032-d9d2-4c5c-9a0c-ac67b90c1b3c', 'Maison Francis Kurkdjian', '{"size": "70 ml / 2.4 fl. oz. Spray Flacon", "top_notes": "Grandiflorum Jasmine from Egypt, Saffron", "base_notes": "Ambergris accord, Woody Musk", "heart_notes": "Bitter Almond from Morocco, Cedarwood", "olfactory_family": "Woody Amber Floral"}'::jsonb, ARRAY['mfk', 'perfume', 'baccaratrouge', 'fragrance', 'luxury', 'french', 'bestseller']::varchar[], 4.75, 4, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('a7638ca6-12a2-4408-baef-63f7ba42a509', 'NM-1D50828E', 'Loewe Mini Puzzle Bag in Classic Calfskin - Tan', 'loewe-mini-puzzle-bag-in-classic-calfskin-tan', 'Jonathan Anderson''s debut bag for Loewe has achieved certified icon status. Its innovative cuboid silhouette is composed of 75 separate leather pieces assembled by hand, allowing the bag to fold completely flat or expand to hold daily essentials.', 'Cuboid shape with distinctive geometric puzzle cut lines, hand-painted edges and embossed Anagram.', 2450.00, 2600.00, 12, '990a5535-5d8a-49d1-b6d5-110e526ce641', 'Loewe', '{"strap": "Detachable and adjustable leather strap (115 cm drop)", "origin": "Artisanal handcrafting in Madrid, Spain", "leather": "Classic Spanish Calfskin with herringbone cotton canvas lining", "hardware": "Palladium metallic hardware"}'::jsonb, ARRAY['loewe', 'puzzle', 'handbag', 'designer', 'leather', 'luxury', 'tan']::varchar[], 3.60, 5, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('f6364af7-66e3-43a9-8c29-145b398658c4', 'NM-D5F362D1', 'Breville The Barista Touch Impress Espresso Machine - Brushed Stainless Steel', 'breville-the-barista-touch-impress-espresso-machine-brushed-stainless-steel', 'Third-wave specialty coffee made effortless at home. The Barista Touch Impress guides you with step-by-step touchscreen feedback, intelligent dosing, assisted precision tamping, and automated silky microfoam calibrated for dairy, almond, oat, and soy milks.', 'Touchscreen guidance, assisted 22lb tamping with auto dose, and Auto MilQ microfoam texturing.', 1499.95, 1699.95, 16, '46d63413-c0ad-4c4b-b437-b73f21ff17f2', 'Breville', '{"grinder": "Precision Baratza European hardened steel burrs with 30 grind settings", "tamping": "Assisted Impress puck system with 7-degree barista twist and 22 lbs force", "milk_system": "Auto MilQ temperature and texture control (Hands-free)", "heating_system": "ThermoJet system with 3-second rapid warm-up"}'::jsonb, ARRAY['breville', 'espresso', 'coffee', 'barista', 'kitchen', 'premium', 'bestseller']::varchar[], 3.67, 3, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('a99bc744-a690-4271-a73a-c6fcc76bf3e0', 'NM-E1204B79', 'Herman Miller Aeron Ergonomic Office Chair (Size B, Graphite Frame with PostureFit SL)', 'herman-miller-aeron-ergonomic-office-chair-size-b-graphite-frame-with-posturefit-sl', 'The benchmark for ergonomic seating since its introduction in 1994, Aeron combines human-centered design with state-of-the-art materials. Engineered with 8Z Pellicle mesh across the seat and back to eliminate pressure points, and adjustable PostureFit SL pads that stabilize the sacrum and support the lumbar region of the spine.', 'Breathable 8Z Pellicle elastomeric suspension, PostureFit SL adjustable spinal support, tilt limiter.', 1495.00, 1695.00, 25, '504946a3-4582-40f9-a4c7-a0f7a03f21fe', 'Herman Miller', '{"size": "Size B (Medium - Fits majority of heights 5''3\" to 6''2\")", "support": "Adjustable PostureFit SL spinal stabilization", "warranty": "12-Year Herman Miller Manufacturer Warranty", "suspension": "8Z Pellicle breathable elastomeric mesh with 8 distinct zones of tension", "adjustments": "Fully adjustable arms (height, depth, pivot), forward seat angle, tilt limiter"}'::jsonb, ARRAY['hermanmiller', 'aeron', 'officechair', 'ergonomic', 'desk', 'workspace', 'luxury']::varchar[], 3.75, 4, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('b36d8555-ae45-4e84-b010-5939343dc674', 'NM-F554973B', 'Fujifilm X100VI Digital Camera - Silver', 'fujifilm-x100vi-digital-camera-silver', 'The ultimate daily documentary camera. Merging timeless analog dial operations with Fujifilm''s cutting-edge 40.2-megapixel sensor, 6-stop 5-axis IBIS, and 6.2K video recording, all packed into a compact all-aluminum body that slips effortlessly into any jacket pocket.', '40.2MP X-Trans CMOS 5 HR sensor, 6.0-stop in-body image stabilization, 20 Film Simulation modes.', 1599.00, 1799.00, 10, '362bd705-5e21-49de-8c73-dcc05a7b2fab', 'Fujifilm', '{"lens": "Fujinon 23mm F2.0 II fixed prime lens (35mm equivalent)", "sensor": "40.2MP back-illuminated X-Trans CMOS 5 HR sensor", "viewfinder": "Advanced Hybrid Viewfinder (Optical OVF + 3.69M dot OLED EVF)", "stabilization": "5-axis In-Body Image Stabilization up to 6.0 stops", "film_simulations": "20 modes including REALA ACE, Classic Chrome, and Nostalgic Neg"}'::jsonb, ARRAY['fujifilm', 'x100vi', 'camera', 'photography', 'classic', 'vintage', 'bestseller']::varchar[], 3.00, 2, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('b4a1634c-fed1-4b2e-8f78-65984c4be8dc', 'NM-14A19C97', 'Bowflex SelectTech 552 Adjustable Dumbbells (Pair, 5 to 52.5 lbs)', 'bowflex-selecttech-552-adjustable-dumbbells-pair-5-to-52-5-lbs', 'These adjustable dumbbells replace 15 sets of weights. Weights adjust from 5 to 52.5 lbs in 2.5 lb increments up to the first 25 lbs. Easy-to-use selection dials for adjusting weights smoothly. Say goodbye to 15 sets of dumbbells cluttering your workout space.', 'Replaces 15 sets of weights with selector dial system, space-efficient home gym training.', 429.00, 549.00, 40, '764547b9-9b3c-4717-9110-361a937c90a0', 'Bowflex', '{"molding": "Durable molding around metal plates for smooth lift-off and quieter workouts", "dimensions": "16.9\" L x 8.3\" W x 9\" H each", "increments": "2.5 lb increments for the first 25 lbs, then 5 lb increments", "weight_range": "5 to 52.5 lbs (2.3 to 23.8 kg) per dumbbell"}'::jsonb, ARRAY['bowflex', 'dumbbells', 'fitness', 'weights', 'homegym', 'strength', 'bestseller']::varchar[], 4.50, 2, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('c0311698-38db-428d-afdd-b6d4ed727a71', 'NM-BB440462', 'Adidas Ultraboost Light Running Shoes - Core Black / Cloud White', 'adidas-ultraboost-light-running-shoes-core-black-cloud-white', 'Experience epic energy with the new Ultraboost Light, our lightest Ultraboost ever. The magic lies in the Light BOOST midsole, a new generation of adidas BOOST. Its unique molecule design achieves the lightest BOOST foam to date and boasts a 10% lower carbon footprint than previous models.', 'Light BOOST midsole with 30% lighter material, Primeknit+ upper, Continental rubber grip.', 189.99, 210.00, 75, '9eb42450-bb43-4b3c-8bb4-c8da95064d72', 'Adidas', '{"drop": "10mm (heel: 30mm / forefoot: 20mm)", "upper": "Primeknit+ FORGED textile made with 50% Parley Ocean Plastic", "weight": "299g (Size 9)", "midsole": "Light BOOST cushioning technology", "outsole": "Continental\u2122 Better Rubber outsole"}'::jsonb, ARRAY['adidas', 'ultraboost', 'running', 'shoes', 'sneakers', 'fitness', 'bestseller']::varchar[], 3.60, 5, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('c383e8b4-abd7-445d-9f7d-1e7288d0b981', 'NM-1189A835', 'ASUS ROG Zephyrus G14 Gaming Laptop (AMD Ryzen 9 8945HS, RTX 4070, 32GB RAM, 1TB SSD)', 'asus-rog-zephyrus-g14-gaming-laptop-amd-ryzen-9-8945hs-rtx-4070-32gb-ram-1tb-ssd', 'Game and create anywhere with the ROG Zephyrus G14. Featuring an all-aluminum CNC machined unibody design with customizable Slash Lighting on the lid, this thin-and-light powerhouse is packed with an AMD Ryzen 9 8945HS processor and NVIDIA GeForce RTX 4070 Laptop GPU, cooled by ROG Intelligent Cooling with liquid metal.', '14" 3K 120Hz ROG Nebula OLED display, ultra-portable 1.5kg chassis with CNC slash lighting.', 1999.99, 2199.99, 25, '47734feb-7f89-4f3a-abd0-52f7d03d0016', 'ASUS', '{"ram": "32GB LPDDR5X 6400MHz", "weight": "1.5 kg (3.31 lbs)", "display": "14\" 3K (2880 x 1800) OLED 120Hz 0.2ms G-SYNC", "storage": "1TB PCIe 4.0 NVMe M.2 SSD", "graphics": "NVIDIA GeForce RTX 4070 8GB GDDR6", "processor": "AMD Ryzen 9 8945HS with Ryzen AI (up to 5.2 GHz)"}'::jsonb, ARRAY['asus', 'rog', 'gaming', 'laptop', 'oled', 'ryzen', 'rtx']::varchar[], 3.60, 5, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('d5dcd5e3-7063-454c-ad0b-f6ba5b353de1', 'NM-AB08E02E', 'Bose QuietComfort Ultra Wireless Noise Cancelling Headphones - White Smoke', 'bose-quietcomfort-ultra-wireless-noise-cancelling-headphones-white-smoke', 'High-fidelity audio and legendary noise cancellation come together with Bose Immersive Audio to create a breakthrough spatial listening experience. CustomTune technology personalizes your sound automatically to your ears'' shape.', 'World-class noise cancellation, groundbreaking spatialized audio, custom tune technology.', 429.00, 479.00, 55, '89916f4b-406e-4035-a407-b87d1a582100', 'Bose', '{"anc": "Bose CustomTune Active Noise Cancellation", "battery": "Up to 24 hours of listening time", "bluetooth": "Bluetooth 5.3 with SimpleSync", "materials": "Plush protein leather earcups, cast aluminum arms", "spatial_audio": "Bose Immersive Audio mode"}'::jsonb, ARRAY['bose', 'headphones', 'quietcomfort', 'anc', 'travel', 'bestseller']::varchar[], 3.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('dd29a091-e69b-4d20-bf89-8032d73bd5f8', 'NM-CDB5E851', 'La Mer Crème de la Mer Ultra-Rich Moisturizing Cream (2 oz / 60ml)', 'la-mer-creme-de-la-mer-ultra-rich-moisturizing-cream-2-oz-60ml', 'The legendary moisturizing cream that started it all. Born from the sea, this legendary cream has the power to transform the skin. In a short time, firmness improves, lines, wrinkles and the look of pores become less visible, skin looks virtually ageless. With cell-renewing Miracle Broth™ and antioxidant Lime Tea.', 'Cell-renewing Miracle Broth™, deep soothing hydration, visibly diminishes lines and wrinkles.', 380.00, 410.00, 35, 'fdcee139-eca4-4b42-a528-9c2555be59b1', 'La Mer', '{"volume": "60 ml / 2 fl. oz.", "benefits": "Deep healing hydration, barrier soothing, age defense", "skin_type": "Ideal for drier skin types", "key_ingredient": "Miracle Broth\u2122 (fermented sea kelp, vitamins, minerals, wheat germ, eucalyptus)"}'::jsonb, ARRAY['lamer', 'cremedelamer', 'skincare', 'moisturizer', 'luxury', 'antiaging']::varchar[], 3.86, 7, True, False) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('dd5c4395-811e-4aaa-97af-ed0f0ba39e15', 'NM-9B190746', 'Dyson Airwrap Multi-Styler Complete Long (Nickel/Copper)', 'dyson-airwrap-multi-styler-complete-long-nickel-copper', 'Style with air, not extreme heat. The Dyson Airwrap multi-styler harnesses an aerodynamic phenomenon called the Coanda effect to attract and wrap hair to the barrel, or surface of the brush. Powered by the Dyson digital motor V9, with intelligent heat control measuring air temperature over 40 times a second to ensure it stays below 302°F.', 'Dries and styles simultaneously using Coanda airflow, no extreme heat damage, 6 versatile attachments.', 599.99, 649.99, 40, '2d6f23b2-6097-4946-85c0-fcb3543a9c20', 'Dyson', '{"motor": "Dyson digital motor V9 (110,000 RPM creating 3.2kPa pressure)", "hair_types": "Engineered for multiple hair types, chest-length or longer", "attachments": "1.2\" & 1.6\" Coanda long barrels, Firm & Soft smoothing brushes, Round volumizing brush, Coanda smoothing dryer", "heat_control": "Intelligent thermistor measurement prevents heat damage"}'::jsonb, ARRAY['dyson', 'airwrap', 'hairstyling', 'curler', 'beauty', 'luxury', 'bestseller']::varchar[], 3.17, 6, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('df012b69-1932-4f75-b62e-154be5738f68', 'NM-985180D1', 'Garmin Forerunner 265 GPS Running Smartwatch with AMOLED Display', 'garmin-forerunner-265-gps-running-smartwatch-with-amoled-display', 'Plan your strategy with daily suggested workouts, course details and more on the race widget. Wake up to your morning report with HRV status to see health insights alongside an overview of sleep, recovery and training outlook. Features multi-band GNSS with SatIQ™ technology for superior positioning accuracy in challenging environments.', 'Vibrant 1.3" AMOLED touchscreen, training readiness metric, wrist-based running dynamics, 13-day battery.', 449.99, 499.99, 55, '5fa2647b-e012-4839-9a2e-d9c46a06f773', 'Garmin', '{"gps": "Multi-band GNSS with SatIQ\u2122 technology", "display": "1.3\" AMOLED Touchscreen with Corning Gorilla Glass 4", "battery_life": "Up to 13 days in smartwatch mode, up to 20 hours in GPS mode", "water_rating": "5 ATM (50 meters swimproof)", "music_storage": "Download songs and playlists from Spotify, Deezer or Amazon Music"}'::jsonb, ARRAY['garmin', 'running', 'smartwatch', 'gps', 'marathon', 'fitness', 'bestseller']::varchar[], 3.75, 8, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('dfcf2cb2-52a6-49c6-9ec0-466e2d29d0df', 'NM-57DFFBE3', 'Sony Alpha A7 IV Full-Frame Mirrorless Interchangeable Lens Camera (Body Only)', 'sony-alpha-a7-iv-full-frame-mirrorless-interchangeable-lens-camera-body-only', 'With groundbreaking performance in both still and movie recording, the α7 IV is the ideal hybrid camera, providing breathtaking imagery alongside on-the-spot delivery and distribution. The 33MP Exmor R sensor combined with the BIONZ XR processing engine delivers high speed and exquisite image quality.', '33MP BSI full-frame sensor, 4K 60p 10-bit 4:2:2, real-time eye autofocus for humans, animals, and birds.', 2498.00, 2699.00, 20, '362bd705-5e21-49de-8c73-dcc05a7b2fab', 'Sony', '{"video": "4K 60p 10-bit 4:2:2 recording, S-Cinetone", "sensor": "33MP Full-Frame Exmor R CMOS BSI Sensor", "autofocus": "759-point Fast Hybrid AF with Real-time Eye AF", "processor": "BIONZ XR Image Processor", "viewfinder": "3.68m-Dot OLED EVF with 120 fps refresh rate", "stabilization": "5-axis steady shot optical in-body image stabilization"}'::jsonb, ARRAY['sony', 'camera', 'mirrorless', 'photography', 'video', '4k', 'pro']::varchar[], 4.20, 5, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('f0843d7b-bd7e-47af-a5e5-9b25985ad2c9', 'NM-CA1F66FD', 'Burberry Small Two-Tone Canvas and Leather TB Bag', 'burberry-small-two-tone-canvas-and-leather-tb-bag', 'A structured silhouette in durable canvas and supple Italian-tanned topstitched leather, accented with a polished gold-plated Thomas Burberry Monogram clasp. Wear on the shoulder, crossbody, or carry as a clutch by detaching the adjustable leather strap.', 'Structured canvas and smooth calf leather shoulder bag with Thomas Burberry Monogram clasp.', 1950.00, 2100.00, 15, '990a5535-5d8a-49d1-b6d5-110e526ce641', 'Burberry', '{"outer": "92% Cotton, 8% Polyurethane with 100% Calf Leather trim", "strap": "Adjustable, detachable crossbody strap", "pockets": "One exterior slip pocket, one interior zip pocket", "hardware": "Polished gold-plated metal monogram clasp", "dimensions": "21 x 6 x 16 cm (8.3 x 2.4 x 6.3 in)"}'::jsonb, ARRAY['burberry', 'bag', 'handbag', 'luxury', 'leather', 'crossbody', 'quietluxury']::varchar[], 5.00, 1, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('f33d5273-d853-4e2d-ae51-cbaee6557138', 'NM-364CD785', 'Apple iPhone 15 Pro Max (256GB, Natural Titanium)', 'apple-iphone-15-pro-max-256gb-natural-titanium', 'iPhone 15 Pro Max features a strong and light aerospace-grade titanium design with textured matte-glass back. It also features a Ceramic Shield front that''s tougher than any smartphone glass. A17 Pro chip brings a monster win for gaming with hardware-accelerated ray tracing. The 48MP Main camera is more advanced than ever, capturing super-high-resolution photos with a new level of detail and color, plus 5x optical zoom.', 'Forged in titanium, A17 Pro chip, customizable Action button, 5x Telephoto camera.', 1199.00, 1299.00, 65, 'b0cedd18-d2ea-4745-9ff6-26099432e969', 'Apple', '{"camera": "48MP Main + 12MP Ultra Wide + 12MP 5x Telephoto", "chassis": "Grade 5 Titanium with Ceramic Shield front", "display": "6.7\" Super Retina XDR OLED (120Hz ProMotion, 2000 nits)", "storage": "256GB NVMe", "processor": "A17 Pro (6-core CPU, 6-core GPU, Neural Engine)", "connectivity": "5G, Wi-Fi 6E, Bluetooth 5.3, USB-C 10Gbps"}'::jsonb, ARRAY['apple', 'iphone', 'smartphone', '5g', 'titanium', 'camera', 'bestseller']::varchar[], 3.67, 3, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('f364f3fa-824f-44d4-a3a3-1cd65ad7e1bf', 'NM-EC3A8DB5', 'Dell XPS 15 9530 (13th Gen Intel Core i9-13900H, 32GB RAM, 1TB SSD, RTX 4070)', 'dell-xps-15-9530-13th-gen-intel-core-i9-13900h-32gb-ram-1tb-ssd-rtx-4070', 'Immerse yourself in content with stunning 3.5K OLED InfinityEdge display that delivers vivid color and sharp contrast. Powered by 13th Gen Intel Core i9 processor and GeForce RTX 4070 graphics, the XPS 15 provides creator-level power in a breathtaking 18mm thin chassis made from precision CNC machined aluminum with carbon fiber palm rest.', '3.5K OLED InfinityEdge touch display, NVIDIA GeForce RTX 4070 8GB GDDR6, CNC machined aluminum.', 2399.00, 2699.00, 30, '47734feb-7f89-4f3a-abd0-52f7d03d0016', 'Dell', '{"ram": "32GB DDR5 4800MHz", "weight": "1.92 kg (4.23 lbs)", "display": "15.6\" 3.5K (3456x2160) OLED Touch 400-nit", "storage": "1TB M.2 PCIe NVMe SSD", "graphics": "NVIDIA GeForce RTX 4070 8GB GDDR6", "processor": "Intel Core i9-13900H (14-core, up to 5.4 GHz)"}'::jsonb, ARRAY['dell', 'xps', 'laptop', 'windows', 'creator', 'oled', 'bestseller']::varchar[], 3.67, 6, True, True) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('f5e36057-0de0-4f75-8f05-2fbea12c6d24', 'NM-115C6B9E', 'Burberry Cotton and Leather Webb Strap Sneakers', 'burberry-cotton-and-leather-webb-strap-sneakers', 'Crafted in Italy from ultra-soft optic white calf leather and breathable canvas lining, the Webb sneaker features statement double buckle straps across the vamp and subtle embossed lettering at the heel counter. Grounded on an ergonomic molded rubber sole.', 'Monochrome slip-on leather sneakers with dual buckle straps and embossed Burberry lettering.', 760.00, 820.00, 35, '9eb42450-bb43-4b3c-8bb4-c8da95064d72', 'Burberry', '{"sole": "100% Durable Ergonomic Rubber", "upper": "100% Calf Leather & Canvas", "origin": "Made in Italy", "closure": "Dual buckle utility straps"}'::jsonb, ARRAY['burberry', 'sneakers', 'footwear', 'luxury', 'minimalist', 'white']::varchar[], 4.14, 7, True, False) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, sku, title, slug, description, short_description, price, compare_at_price, stock_quantity, category_id, brand, attributes, tags, avg_rating, review_count, is_published, is_featured) VALUES ('fb53caf1-6f76-4217-b036-ac4efe5bea89', 'NM-EDF43626', 'Dior Sauvage Eau de Parfum Spray for Men (3.4 oz / 100ml)', 'dior-sauvage-eau-de-parfum-spray-for-men-3-4-oz-100ml', 'Dior Sauvage Eau de Parfum exudes sensual and mysterious facets. Calabrian bergamot adds its signature juicy freshness. Spicy notes lend fullness and sensuality, as the fragrance is enveloped in the smoky accents of Papua New Guinean vanilla absolute for greater virility. Inspired by the magic hour of twilight in the desert.', 'Radiant Calabrian bergamot, smoky Papua New Guinean vanilla absolute, sensually woody trail.', 165.00, 185.00, 65, 'c1406032-d9d2-4c5c-9a0c-ac67b90c1b3c', 'Dior', '{"notes": "Reggio Bergamot, Sichuan Pepper, Ambroxan, Papua New Guinean Vanilla", "volume": "100 ml / 3.4 oz", "scent_type": "Warm Woods with Fresh Citrus", "fragrance_family": "Earthy & Woody"}'::jsonb, ARRAY['dior', 'sauvage', 'cologne', 'perfume', 'fragrance', 'men', 'luxury', 'bestseller']::varchar[], 4.00, 3, True, True) ON CONFLICT (id) DO NOTHING;
