INSERT INTO reviews (id, product_id, user_id, rating, title, body, is_verified_purchase, created_at) VALUES ('6b60fccf-b7bd-4982-9c70-775895b2589d', '2b9bfea1-72ca-4e12-bf4c-5be1900ce6b6', 'd77b9087-0e85-495e-bc7b-7531bb23cf93', 3, 'Decent, but not amazing', 'The Apple MacBook Pro 16" (M3 Max, 36GB Unified Memory, 1TB SSD) - Space Black is okay for the price. The quality is acceptable for the price range. However, the performance is sluggish and laggy. It gets the job done but doesn''t wow.', False, '2026-09-11 11:30:43.797204+00:00') ON CONFLICT (id) DO NOTHING;
