INSERT INTO reviews (id, product_id, user_id, rating, title, body, is_verified_purchase, created_at) VALUES ('0fae1620-40ad-4f36-b183-04245378bbe4', 'f364f3fa-824f-44d4-a3a3-1cd65ad7e1bf', 'fbe8f458-77d9-4032-afce-d5d74035229b', 1, 'Terrible experience', 'The Dell XPS 15 9530 (13th Gen Intel Core i9-13900H, 32GB RAM, 1TB SSD, RTX 4070) is awful. the battery drains much faster than advertised. Complete waste of money. Returning immediately.', True, '2026-09-11 11:30:43.797204+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO reviews (id, product_id, user_id, rating, title, body, is_verified_purchase, created_at) VALUES ('8a3ca958-6540-491a-b6f0-45bd501ee0a7', 'c383e8b4-abd7-445d-9f7d-1e7288d0b981', '1a38406b-f00c-4d25-8b4b-fb40a48f8ea6', 5, 'Best purchase this year', 'The ASUS ROG Zephyrus G14 Gaming Laptop (AMD Ryzen 9 8945HS, RTX 4070, 32GB RAM, 1TB SSD) is genuinely outstanding. Sound quality is crystal clear with great bass response. The build quality is exceptional and it performs even better than advertised.', False, '2026-09-11 11:30:43.797204+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO reviews (id, product_id, user_id, rating, title, body, is_verified_purchase, created_at) VALUES ('939bb7af-3e20-40a3-8530-8146c907e77f', 'c383e8b4-abd7-445d-9f7d-1e7288d0b981', '3a69da49-0dfb-4066-aeef-29899994161b', 2, 'Could be better', 'I had high hopes for the ASUS ROG Zephyrus G14 Gaming Laptop (AMD Ryzen 9 8945HS, RTX 4070, 32GB RAM, 1TB SSD) but the battery drains much faster than advertised. The The battery life is impressive, easily lasts the full day is nice, but it doesn''t make up for the issues.', False, '2026-09-11 11:30:43.797204+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO reviews (id, product_id, user_id, rating, title, body, is_verified_purchase, created_at) VALUES ('882acde2-6dbd-4dc0-b9fd-6e29d8912d34', 'c383e8b4-abd7-445d-9f7d-1e7288d0b981', '529cddf3-7a47-4570-aa65-eb6df57e4490', 4, 'Great product with minor caveats', 'The ASUS ROG Zephyrus G14 Gaming Laptop (AMD Ryzen 9 8945HS, RTX 4070, 32GB RAM, 1TB SSD) is really solid overall. Sound quality is crystal clear with great bass response. My only small complaint is the companion app could use some UI improvements, but it doesn''t detract from the experience.', True, '2026-09-11 11:30:43.797204+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO reviews (id, product_id, user_id, rating, title, body, is_verified_purchase, created_at) VALUES ('8c5f9164-7a2a-443e-adbb-48d0a3b459c1', 'c383e8b4-abd7-445d-9f7d-1e7288d0b981', '541b65b9-1165-4f0e-965c-5855e0013995', 4, 'Solid choice', 'The ASUS ROG Zephyrus G14 Gaming Laptop (AMD Ryzen 9 8945HS, RTX 4070, 32GB RAM, 1TB SSD) delivers on its promises. Comfort level is outstanding, even after hours of use. It''s not perfect — it takes a moment to boot up initially — but I''d still recommend it.', True, '2026-09-11 11:30:43.797204+00:00') ON CONFLICT (id) DO NOTHING;
